import { PropsWithChildren } from 'react';

import {
  TimeseriesThresholdPosition,
  TimeseriesThresholdData,
} from '../../core/types/thresholds.js';

/** Props for the TimeseriesChart.Threshold slot component*/
export interface TimeseriesChartThresholdProps {
  /** The threshold data to be graphed by the component */
  data: TimeseriesThresholdData;
  /** The unique color picked for this timeseries representation in HEX, RGB, Color Token or HSL.*/
  color: string;
  /** The position of the threshold relative to the timeseries chart. */
  position?: TimeseriesThresholdPosition;
  /** Whereas to show the ranges filled or only the strokes */
  strokeOnly?: boolean;
  /**
   * Label to be shown in the threshold tooltip.
   * @defaultValue "Threshold"
   */
  label?: string;
}

export const Threshold = (
  props: PropsWithChildren<TimeseriesChartThresholdProps>,
) => null;
